using BARANG.Core.Api.Errors;using BARANG.Core.Application.Abstractions.Companies;using BARANG.Core.Application.Background;using BARANG.Core.Domain.Common;using BARANG.Core.Domain.Security;
namespace BARANG.Core.Api.Background;
public static class BackgroundEndpoints
{public static IEndpointRouteBuilder MapBackgroundEndpoints(this IEndpointRouteBuilder e){RouteGroupBuilder n=e.MapGroup("/api/v1/notifications");n.MapGet("/mine",async(bool?unread,string?search,string?category,string?priority,bool?actionable,DateTimeOffset?fromUtc,DateTimeOffset?toUtc,int?page,int?pageSize,INotificationAdministration s,CancellationToken ct)=>Map(await s.MyAsync(new(unread,search,category,priority,actionable,fromUtc,toUtc,page??1,pageSize??20),ct))).RequireAuthorization(SecurityPermissions.NotificationRead);n.MapPost("/{id:guid}/read",async(Guid id,VersionRequest r,INotificationAdministration s,CancellationToken ct)=>Map(await s.MarkReadAsync(id,r.Version,ct))).RequireAuthorization(SecurityPermissions.NotificationRead);n.MapPost("/read-all",async(INotificationAdministration s,CancellationToken ct)=>Map(await s.MarkAllReadAsync(ct))).RequireAuthorization(SecurityPermissions.NotificationRead);n.MapPost("/queue",async(NotificationRequest r,INotificationAdministration s,CancellationToken ct)=>Map(await s.QueueAsync(r,ct),true)).RequireAuthorization(SecurityPermissions.NotificationManage);RouteGroupBuilder b=e.MapGroup("/api/v1/background").RequireAuthorization(SecurityPermissions.BackgroundJobReview);b.MapPost("/outbox/dispatch",async(IOutboxDispatcher s,CancellationToken ct)=>Results.Ok(await s.DispatchAllAsync(ct)));b.MapGet("/dead-letters",async(INotificationAdministration s,CancellationToken ct)=>Map(await s.DeadLettersAsync(ct)));b.MapPost("/dead-letters/{id:guid}/retry",async(Guid id,VersionRequest r,INotificationAdministration s,CancellationToken ct)=>Map(await s.RetryAsync(id,r.Version,ct)));b.MapPost("/schedulers/sla",async(ISlaScheduler s,CancellationToken ct)=>{await s.RunAsync(ct);return Results.NoContent();});b.MapPost("/schedulers/files",async(IFileProcessingScheduler s,CancellationToken ct)=>{await s.RunAsync(ct);return Results.NoContent();});b.MapDelete("/cache/{culture}/{identity}",async(string culture,string identity,ICompanyContext c,IApplicationCache cache,CancellationToken ct)=>{await cache.RemoveAsync(new(c.RequireCompanyId(),culture,identity),ct);return Results.NoContent();});return e;}private static IResult Map(Result r)=>r.IsSuccess?Results.NoContent():Results.Problem(ApiProblemDetailsMapper.Create(r.Error,"background",null));private static IResult Map<T>(Result<T>r,bool created=false)=>r.IsSuccess?Results.Json(r.Value,statusCode:created?201:200):Results.Problem(ApiProblemDetailsMapper.Create(r.Error,"background",null));public sealed record VersionRequest(long Version);}
